/*
 * A039069  Numbers whose base-8 representation has the same number of 3's and
 *          6's.
 * https://oeis.org/A039069
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base, easy
 * Formula:   a(n) is the nth non‑negative integer whose base‑8 representation
 *            contains an equal number of digits 3 and 6. The sequence is
 *            generated by brute‑force enumeration and memoisation to support
 *            arbitrary calling order
 * Range:     u8 n <= 68, u16 n <= 68, u32 n <= 68, u64 n <= 68, u128 n <= 68,
 *            big any n
 * Helpers:   equal_3_6
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stddef.h>
#include <stdint.h>
#include <stdbool.h>
#include <stdlib.h>
#include "../utils/equal_3_6.h"

/* The main sequence function. */
seq_t a(idx_t n)
{
    /* Static memoised cache. */
    static seq_t *cache        = NULL;
    static idx_t  cache_sz     = 0;
    static idx_t  cache_cap    = 0;
    static idx_t  scanned_now  = 0;   /* next integer to test */

    /* Ensure we can hold n entries. */
    if (cache_sz < n && (cache == NULL || cache_cap < cache_sz + n)) {
        idx_t new_cap = cache_cap == 0 ? 16 : cache_cap << 1;
        while (new_cap < cache_sz + n) new_cap <<= 1;
        cache = (seq_t *)realloc(cache, (size_t)new_cap * sizeof(seq_t));
        cache_cap = new_cap;
    }

    /* Scan forward until we have at least n elements. */
    while (cache_sz < n) {
        if (equal_3_6(scanned_now))
            cache[cache_sz++] = (seq_t)scanned_now;
        ++scanned_now;
    }

    return cache[n - 1];
}
